"use client"

import CraftBeerProductTemplate from "@/components/ui/craft-beer-product-template"

// Every photo is generated by us (Canva generate-image, 2026-11-04) for the
// invented Toofan Brewing Co., cut out (locally, or with Adobe's background removal for the mug and cans) and inlined as AVIF so the demo
// needs no network beyond the Google Fonts stylesheet.
const IMG_BOTTLE =
  "data:image/avif;base64,"
const IMG_B650 =
  "data:image/avif;base64,"
const IMG_CAN330 =
  "data:image/avif;base64,"
const IMG_CAN500 =
  "data:image/avif;base64,"
const IMG_TAP =
  "data:image/avif;base64,"
const IMG_GLASS =
  "data:image/avif;base64,"
const IMG_BREWER =
  "data:image/avif;base64,"
const IMG_FOOD =
  "data:image/avif;base64,"

export default function Demo() {
  // w-full is load-bearing: 21st centres every demo in a flex wrapper, and a
  // flex item left at width:auto shrinks to fit its contents.
  return (
    <div className="w-full">
      <CraftBeerProductTemplate
        bottle={IMG_BOTTLE}
        glass={IMG_GLASS}
        videoPoster={IMG_BREWER}
        recipeImage={IMG_FOOD}
        packs={[
          { label: "On tap", src: IMG_TAP, alt: "Toofan tap handle", scale: 0.92 },
          { label: "650 ml bottles", detail: "Singles", src: IMG_B650, alt: "650 ml bottle", scale: 1 },
          { label: "330 ml bottles", detail: "6- or 12-pack", scale: 0.74, slot: true },
          { label: "330 ml cans", detail: "4-pack", src: IMG_CAN330, alt: "330 ml can", scale: 0.56 },
          { label: "500 ml cans", detail: "Singles", src: IMG_CAN500, alt: "500 ml can", scale: 0.74 },
        ]}
      />
    </div>
  )
}
